css:
[data-slot="menu-popup"] [data-variant="destructive"][data-highlighted] { background-color: var(--error-surface) !important; }
:is([data-slot="dialog-footer"], [data-slot="alert-dialog-footer"]) { background-color: transparent !important; border-top-color: transparent !important; }
/* flat buttons: zero Tailwind's shadow vars only, so focus rings (also box-shadow) survive */
:is([data-slot="button"], [data-slot$="-close"], [data-slot$="-action"]), :is([data-slot="button"], [data-slot$="-close"], [data-slot$="-action"])::before { --tw-shadow: 0 0 #0000 !important; --tw-inset-shadow: 0 0 #0000 !important; }
:root { --font-weight-medium: 510 !important; --font-weight-semibold: 590 !important; --font-weight-bold: 680 !important; --default-font-feature-settings: "cv01", "ss03" !important; --radius: .375rem !important; --control-radius: .375rem !important; --surface-grain: none !important; }
/* inset main panel: sidebar-inset is not a stable T3 selector, recheck after nightly updates */
[data-slot="sidebar-inset"] { margin: 8px 8px 8px 0; border: 1px solid var(--border); border-radius: 12px; overflow: hidden; height: calc(100dvh - 16px) !important; min-height: 0 !important; }
/* the inset panel border replaces the sidebar edge; avoid a double separator */
[data-slot="sidebar-container"] { border-right-color: transparent !important; }
/* move top-right controls clear of the inset margin + radius */
:root { --workspace-controls-right: calc(env(safe-area-inset-right) + 1.25rem) !important; }
.wco { --workspace-controls-right: calc(100vw - env(titlebar-area-width, 100vw) - env(titlebar-area-x, 0px) + 1.25rem) !important; }
/* Linear weights: strong text is semibold, not 700 */
strong, b, .chat-markdown strong { font-weight: var(--font-weight-semibold) !important; }
/* sidebar rows: lighter than font-medium (510) so titles do not read as bold */
:is([data-thread-item], [data-sidebar-row]) .font-medium { font-weight: 450 !important; }
/* sidebar thread & draft cards: drop py-0.5 so the list's gap-px leaves 1px between rows */
:is(li[data-thread-item], li:has(> [data-sidebar-row])) { padding-block: 0 !important; }
/* top-right controls: shift down by the inset margin so top gap matches the right gap */
[class*="right-[var(--workspace-controls-right)]"][class*="top-[var(--workspace-controls-top)]"] { top: calc(var(--workspace-controls-top) + 8px) !important; gap: 1px !important; }
[class*="right-[var(--workspace-controls-right)]"] .gap-1 { gap: 1px !important; }
/* floating surfaces: one Linear-style recipe instead of four shadow/border/glass variants */
:root { --popup-shadow: 0 2px 6px rgb(0 0 0 / 4%), 0 1px 1px rgb(0 0 0 / 3%); }
:root.dark { --popup-shadow: 0 2px 8px rgb(0 0 0 / 24%), 0 1px 1px rgb(0 0 0 / 20%); }
:is([data-slot="menu-popup"], [data-slot="select-popup"], [data-slot="popover-popup"]:not(.bg-transparent), [data-slot="preview-card-popup"], [data-slot="tooltip-popup"], [data-slot="autocomplete-popup"], [data-slot="combobox-positioner"] > span, [data-slot="toast-popup"], .dropdown-glass:not([data-thread-details-card])) { background: var(--popover) !important; border: 1px solid var(--border) !important; border-radius: 8px !important; box-shadow: var(--popup-shadow) !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; }
[data-slot="tooltip-popup"] { border-radius: 6px !important; }
:is([data-slot="menu-popup"], [data-slot="select-popup"], [data-slot="popover-popup"], [data-slot="preview-card-popup"], [data-slot="tooltip-popup"], [data-slot="autocomplete-popup"], [data-slot="combobox-positioner"] > span, [data-slot="toast-popup"], .dropdown-glass:not([data-thread-details-card]))::before { display: none !important; }
/* toast close: same surface as popups, shown only on hover or keyboard focus */
[data-slot="toast-close"] { background: var(--popover) !important; border: 1px solid var(--border) !important; box-shadow: var(--popup-shadow) !important; backdrop-filter: none !important; opacity: 0; transition: opacity .1s; }
[data-slot="toast-popup"]:hover [data-slot="toast-close"], [data-slot="toast-close"]:focus-visible { opacity: 1; }
/* hide scrollbars everywhere (native and scroll-area); scrolling still works */
* { scrollbar-width: none !important; }
*::-webkit-scrollbar { display: none !important; }
[data-slot="scroll-area-scrollbar"] { display: none !important; }
/* thread details card: white + border in light mode, changed-files surface (input/20 over background) in dark mode */
[data-thread-details-card] { background: var(--background) !important; border: 1px solid var(--border) !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; border-radius: var(--radius-lg) !important; }
.dark [data-thread-details-card] { background: color-mix(in oklab, var(--input) 20%, var(--background)) !important; border-color: transparent !important; }
/* pill buttons */
:is([data-slot="button"], [data-slot="toggle"], [data-slot="toggle-group"], [class*="active:not([aria-haspopup])]:scale-[0.97]"]), :is([data-slot="button"], [data-slot="toggle"], [data-slot="toggle-group"], [class*="active:not([aria-haspopup])]:scale-[0.97]"])::before { border-radius: 9999px !important; }
/* subtler row hovers (thread details card and alike): app uses white 7.5% / black 5.5% */
.dark [class*="hover:bg-white/[0.075]"]:hover { background-color: rgb(255 255 255 / 4%) !important; }
:root:not(.dark) [class*="hover:bg-black/[0.055]"]:hover { background-color: rgb(0 0 0 / 3%) !important; }
/* button groups (split buttons): one pill for the whole group, square inner edges */
:is([data-slot="group"] > [data-slot], [data-slot="group"] > [data-slot]::before) { border-radius: 0 !important; }
:is([data-slot="group"]:not([class*="flex-col"]) > [data-slot]:first-child, [data-slot="group"]:not([class*="flex-col"]) > [data-slot]:first-child::before) { border-start-start-radius: 9999px !important; border-end-start-radius: 9999px !important; }
:is([data-slot="group"]:not([class*="flex-col"]) > [data-slot]:last-child, [data-slot="group"]:not([class*="flex-col"]) > [data-slot]:last-child::before) { border-start-end-radius: 9999px !important; border-end-end-radius: 9999px !important; }
:is([data-slot="group"][class*="flex-col"] > [data-slot]:first-child, [data-slot="group"][class*="flex-col"] > [data-slot]:first-child::before) { border-top-left-radius: var(--radius-lg) !important; border-top-right-radius: var(--radius-lg) !important; }
:is([data-slot="group"][class*="flex-col"] > [data-slot]:last-child, [data-slot="group"][class*="flex-col"] > [data-slot]:last-child::before) { border-bottom-left-radius: var(--radius-lg) !important; border-bottom-right-radius: var(--radius-lg) !important; }
/* pill buttons keep the square inner edge of split buttons (rounded-e-none / rounded-s-none) */
:is([data-slot="button"], [class*="active:not([aria-haspopup])]:scale-[0.97]"]):is([class~="rounded-e-none"]) { border-start-end-radius: 0 !important; border-end-end-radius: 0 !important; }
:is([data-slot="button"], [class*="active:not([aria-haspopup])]:scale-[0.97]"]):is([class~="rounded-s-none"]) { border-start-start-radius: 0 !important; border-end-start-radius: 0 !important; }
/* select-style buttons (e.g. Select ref): one hover for the whole control, not a second one on the label or chevron */
:is([data-slot="select-label"], [data-slot="select-icon"]):hover { background-color: transparent !important; }
/* composer bottom bar: uniform 28px controls, flat send/stop, and cleaner spacing inside the model pill */
[data-chat-composer-footer="true"] { --composer-bar-h: 2rem; padding-inline: 0.625rem !important; padding-bottom: 0.625rem !important; }
@media (min-width: 640px) { [data-chat-composer-footer="true"] { --composer-bar-h: 1.75rem; } }
[data-chat-composer-footer="true"] :is([data-chat-composer-actions="right"], [data-chat-composer-compact-send="true"]) { gap: 0.125rem !important; }
[data-chat-composer-footer="true"] [data-chat-composer-controls="footer"] { gap: 0.25rem !important; }
[data-chat-composer-footer="true"] [data-chat-composer-actions="right"] > div:not([data-chat-composer-controls]):not([data-chat-composer-compact-send]) { gap: 0.375rem !important; }
[data-chat-composer-footer="true"] :is([data-chat-composer-actions="right"], [data-chat-composer-compact-send="true"]) > :is(button[class*="sm:h-8"][class*="sm:w-8"], span:has(> button[class*="sm:h-8"][class*="sm:w-8"])) { margin-inline-start: 0.375rem !important; }
[data-chat-composer-footer="true"] :is([data-chat-provider-model-picker="true"], [data-resting-block] button, [data-chat-composer-compact-send="true"] > button) { height: var(--composer-bar-h) !important; padding-inline: 0.625rem !important; font-size: 0.8125rem !important; border-radius: 9999px !important; }
[data-chat-composer-footer="true"] :is([data-composer-block-icon-only="true"] button, [data-resting-controls-overflow] button) { width: var(--composer-bar-h) !important; height: var(--composer-bar-h) !important; padding-inline: 0 !important; }
[data-chat-composer-footer="true"] button[class*="sm:h-8"][class*="sm:w-8"] { width: var(--composer-bar-h) !important; height: var(--composer-bar-h) !important; --tw-shadow: 0 0 #0000 !important; --tw-inset-shadow: 0 0 #0000 !important; }
[data-chat-composer-footer="true"] button[class*="sm:h-8"][class*="sm:w-8"]:hover { scale: 1 !important; }
[data-chat-composer-footer="true"] button[class*="sm:h-8"][class*="sm:w-8"]:active:not(:disabled) { scale: 0.97 !important; }
[data-chat-composer-footer="true"] [data-chat-provider-model-picker="true"] > span { gap: 0.5rem !important; }
[data-chat-composer-footer="true"] [data-chat-provider-model-picker="true"] [data-chat-provider-model-picker-icon] svg { margin-inline: 0 !important; }
[data-chat-composer-footer="true"] [data-chat-provider-model-picker="true"] > span > [data-chat-provider-model-picker-label] + span:not([data-slot]) { margin-inline-start: 0.125rem !important; gap: 0.5rem !important; }
[data-chat-composer-footer="true"] [data-chat-provider-model-picker="true"] [data-composer-secondary-trait] { color: var(--muted-foreground) !important; font-variant-numeric: tabular-nums; }
/* command palette: Linear cmd-K look (640px wide, flat 12px surface, no search icon, 40px rows, keycap shortcuts) */
[data-command-palette] { max-width: 640px !important; overflow: hidden; background: var(--popover) !important; border: 1px solid var(--border) !important; border-radius: 12px !important; box-shadow: 0 16px 70px rgb(0 0 0 / 18%) !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; }
.dark [data-command-palette] { box-shadow: 0 16px 70px rgb(0 0 0 / 50%) !important; }
[data-command-palette] [data-slot="autocomplete-start-addon"] { display: none !important; }
[data-command-palette] [class*="px-[var(--command-shell-inset)]"] { padding-block: .25rem !important; }
/* T3 pads the input with an !important calc(var(--command-shell-inset) + 1.5rem) that theme rules cannot outrank; -1rem here leaves .5rem, so text lines up with group labels at 16px */
[data-command-palette] [data-slot="autocomplete-input"] { --command-shell-inset: -1rem; height: 2.75rem !important; font-size: 14px !important; }
[data-command-palette] [data-slot="command-list"] { padding-top: 0 !important; scroll-padding-top: 0 !important; }
[data-command-palette] [data-slot="command-group-label"] { padding-inline: .5rem !important; padding-block: 0 .375rem !important; font-size: 13px !important; font-weight: 450 !important; color: var(--muted-foreground) !important; }
[data-command-palette] [data-slot="command-item"] { min-height: 2.5rem !important; padding-inline: .5rem !important; gap: .625rem !important; border-radius: 8px !important; font-size: 14px !important; }
/* T3 pins the icon to the top (self-start) for two-line rows; single-line rows are taller here, so center them */
[data-command-palette] [data-slot="command-item"] > [class~="self-start"]:not(:has(+ [class~="flex-col"])) { align-self: center !important; padding-top: 0 !important; }
[data-command-palette] [data-slot="command-item"]:is([data-highlighted], [data-highlighted][data-selected]) { background-color: color-mix(in oklab, var(--foreground) 5%, transparent) !important; }
.dark [data-command-palette] [data-slot="command-item"]:is([data-highlighted], [data-highlighted][data-selected]) { background-color: color-mix(in oklab, var(--foreground) 7%, transparent) !important; }
[data-command-palette] [data-slot="command-shortcut"] { display: inline-flex; align-items: center; justify-content: center; height: 1.25rem; min-width: 1.25rem; padding-inline: .3125rem; border: 1px solid var(--border); border-radius: 4px; font-size: 11px !important; letter-spacing: .15em !important; text-indent: .15em; color: var(--muted-foreground) !important; }
[data-command-palette] [data-slot="command-footer"] { display: none !important; }
